            state_topic: `${baseTopic}/alarm/active`,
            payload_on: "ON",
            payload_off: "OFF",
            device_class: "problem",
            icon: "mdi:alert-circle",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    m.push({
        topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_visual_status/config`,
        payload: {
            name: `${bmsName} Visual Status`,
            unique_id: `${deviceID}_visual_status_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_visual_status`,
            default_entity_id: `sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_visual_status`,
            state_topic: `${baseTopic}/alarm/visual_status`,
            icon: "mdi:gauge",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    m.push({
        topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_status/config`,
        payload: {
            name: `${bmsName} Alarm Status`,
            unique_id: `${deviceID}_alarm_status_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_status`,
            default_entity_id: `sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_status`,
            state_topic: `${baseTopic}/alarm/status`,
            icon: "mdi:text-box-outline",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    m.push({
        topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_list/config`,
        payload: {
            name: `${bmsName} Alarm List`,
            unique_id: `${deviceID}_alarm_list_v2`,
            object_id: `${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_list`,
            default_entity_id: `sensor.${baseTopic.toLowerCase()}_${bmsName.toLowerCase()}_alarm_list`,
            state_topic: `${baseTopic}/alarm/list`,
            icon: "mdi:format-list-bulleted",
            device: {
                identifiers: [deviceID],
                name: bmsName
            }
        },
        retain: true
    });

    return m;
}

function buildState() {
    const out = [];

    out.push({
        topic: `${baseTopic}/alarm/active`,
        payload: alarmData.has_alarms ? "ON" : "OFF",
        retain: true
    });

    out.push({
        topic: `${baseTopic}/alarm/visual_status`,
        payload: alarmData.has_alarms
            ? `🚨 ${alarmData.alarm_count} alarme(s)`
            : "✅ No alarm",
        retain: true
    });

    out.push({
        topic: `${baseTopic}/alarm/status`,
        payload: alarmData.alarm_details.status,
        retain: true
    });

    out.push({
        topic: `${baseTopic}/alarm/list`,
        payload: alarmData.active_alarms.length > 0
            ? alarmData.active_alarms.map(a => a.description).join(", ")
            : "No alarms",
        retain: true
    });

    return out;
}

// ------------------------------------------------------------------
