                object_id: `${baseTopic.toLowerCase()}_bms_${bmsId}_visual_status`,
                default_entity_id: `sensor.${baseTopic.toLowerCase()}_bms_${bmsId}_visual_status`,
                state_topic: `${baseTopic}/alarm/visual_status`,
                entity_category: "diagnostic",
                icon: "mdi:eye",
                device: deviceBlock()
            }),
            retain: true
        },
        {
            topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_bms_${bmsId}_alarm_status/config`,
            payload: JSON.stringify({
                name: `BMS ${bmsId} Alarm Status`,
                unique_id: `${deviceID}_alarm_status_v2`,
                object_id: `${baseTopic.toLowerCase()}_bms_${bmsId}_alarm_status`,
                default_entity_id: `sensor.${baseTopic.toLowerCase()}_bms_${bmsId}_alarm_status`,
                state_topic: `${baseTopic}/alarm/status`,
                entity_category: "diagnostic",
                icon: "mdi:alert-outline",
                device: deviceBlock()
            }),
            retain: true
        },
        {
            topic: `${discoveryPrefix}/sensor/${baseTopic.toLowerCase()}_bms_${bmsId}_alarm_list/config`,
            payload: JSON.stringify({
                name: `BMS ${bmsId} Alarm List`,
                unique_id: `${deviceID}_alarm_list_v2`,
                object_id: `${baseTopic.toLowerCase()}_bms_${bmsId}_alarm_list`,
                default_entity_id: `sensor.${baseTopic.toLowerCase()}_bms_${bmsId}_alarm_list`,
                state_topic: `${baseTopic}/alarm/list`,
                entity_category: "diagnostic",
                icon: "mdi:format-list-bulleted",
                device: deviceBlock()
            }),
            retain: true
        }
    ];
}

function buildAlarmStateMessages() {
    return [
        {
            topic: `${baseTopic}/alarm/active`,
            payload: alarmData.has_alarms ? "ON" : "OFF",
            retain: true
        },
        {
            topic: `${baseTopic}/alarm/visual_status`,
            payload: alarmData.has_alarms
                ? `🚨 ${alarmData.alarm_count} alarme(s)`
                : "✅ Aucune alarme",
            retain: true
        },
        {
            topic: `${baseTopic}/alarm/status`,
            payload: alarmData.alarm_details?.status || "No BMS alarms",
            retain: true
        },
        {
            topic: `${baseTopic}/alarm/list`,
            payload: alarmData.active_alarms && alarmData.active_alarms.length > 0
                ? alarmData.active_alarms.map(a => a.description).join(", ")
                : "",
            retain: true
        }
    ];
}

let out = [];

if (!discoveryAlreadySent) {
    out = out.concat(buildAlarmDiscoveryMessages());
    flow.set(discoveryKey, true);
    node.warn(`✓ Discovery alarmes envoyé pour BMS ${bmsId}`);
}

out = out.concat(buildAlarmStateMessages());

return [out];
